// generated by timing.js: do not edit
(function () { const TL = {"DURATION":392.05,"lines":[{"at":1.2,"dur":1.25,"text":"You look up from the beach.","who":"narrator","scene":"beach"},{"at":2.71,"dur":1.46,"text":"A plane crosses the sky.","who":"narrator","scene":"beach"},{"at":4.43,"dur":1.65,"text":"You can read the name on its tail.","who":"narrator","scene":"beach"},{"at":6.34,"dur":1.18,"text":"And the pilot's face...","who":"narrator","scene":"beach"},{"at":8.07,"dur":0.64,"text":"waving.","who":"narrator","scene":"beach"},{"at":9.87,"dur":1.13,"text":"You glance at the Moon.","who":"narrator","scene":"moon"},{"at":11.26,"dur":2,"text":"Craters. Mountains. Shadows.","who":"narrator","scene":"moon"},{"at":13.52,"dur":1.04,"text":"No telescope.","who":"narrator","scene":"moon"},{"at":15.72,"dur":2.5,"text":"A friend points at a hill two kilometers away.","who":"narrator","scene":"hill"},{"at":18.68,"dur":0.88,"text":"What's that?","who":"friend","scene":"hill"},{"at":20.18,"dur":0.8,"text":"You squint.","who":"narrator","scene":"hill"},{"at":21.24,"dur":0.59,"text":"A man.","who":"narrator","scene":"hill"},{"at":22.09,"dur":1.09,"text":"Eating a sandwich.","who":"narrator","scene":"hill"},{"at":23.44,"dur":0.55,"text":"Ham...","who":"narrator","scene":"hill"},{"at":24.54,"dur":1.17,"text":"and too much mustard.","who":"narrator","scene":"hill"},{"at":26.87,"dur":1.08,"text":"Your name is Theo.","who":"narrator","scene":"plate"},{"at":28.21,"dur":2.94,"text":"A British driving test asks you to read a number plate...","who":"narrator","scene":"plate"},{"at":31.7,"dur":1.13,"text":"from twenty meters.","who":"narrator","scene":"plate"},{"at":33.09,"dur":0.51,"text":"You?","who":"narrator","scene":"plate"},{"at":34.02,"dur":0.98,"text":"Two kilometers.","who":"narrator","scene":"plate"},{"at":36.16,"dur":4.11,"text":"Normal eyes pick out details about one sixtieth of a degree wide.","who":"narrator","scene":"acuity"},{"at":40.53,"dur":0.6,"text":"Yours?","who":"narrator","scene":"acuity"},{"at":41.55,"dur":1.31,"text":"A hundred times finer.","who":"narrator","scene":"acuity"},{"at":44.02,"dur":1.03,"text":"But here's the rule.","who":"narrator","scene":"rule"},{"at":45.31,"dur":2.06,"text":"Your eyes got a hundred times sharper.","who":"narrator","scene":"rule"},{"at":47.63,"dur":1.2,"text":"Your legs did not.","who":"narrator","scene":"rule"},{"at":49.09,"dur":2.31,"text":"You can spot trouble two kilometers away.","who":"narrator","scene":"rule"},{"at":51.66,"dur":1.14,"text":"You still reach it...","who":"narrator","scene":"rule"},{"at":53.35,"dur":1.06,"text":"at human speed.","who":"narrator","scene":"rule"},{"at":55.57,"dur":2.63,"text":"So what if your eyesight was a hundred times sharper?","who":"narrator","scene":"title"},{"at":59.52,"dur":1.75,"text":"Plus: you never need glasses.","who":"narrator","scene":"class"},{"at":61.53,"dur":3.15,"text":"From the back row, you can read the teacher's notes on her desk.","who":"narrator","scene":"class"},{"at":64.94,"dur":0.63,"text":"Do you?","who":"narrator","scene":"class"},{"at":65.99,"dur":0.57,"text":"Never.","who":"narrator","scene":"class"},{"at":66.82,"dur":0.69,"text":"Mostly.","who":"narrator","scene":"class"},{"at":67.77,"dur":2.23,"text":"Minus: you can read everything else too.","who":"narrator","scene":"class"},{"at":70.26,"dur":1.34,"text":"Every pore on her nose.","who":"narrator","scene":"class"},{"at":71.86,"dur":1.03,"text":"Every grey hair...","who":"narrator","scene":"class"},{"at":73.44,"dur":1.47,"text":"she thinks nobody can see.","who":"narrator","scene":"class"},{"at":75.37,"dur":2.32,"text":"Okay, class. Why is Theo staring at me?","who":"teacher","scene":"class"},{"at":79.01,"dur":3.43,"text":"At the football match, you sit in the cheapest seat in the stadium.","who":"narrator","scene":"stadium"},{"at":82.7,"dur":1.98,"text":"You can still read the stitching on the ball.","who":"narrator","scene":"stadium"},{"at":85.84,"dur":3.14,"text":"In birdwatching club, everyone shares binoculars.","who":"narrator","scene":"birds"},{"at":89.24,"dur":1.18,"text":"You count the feathers...","who":"narrator","scene":"birds"},{"at":90.97,"dur":0.74,"text":"out loud.","who":"narrator","scene":"birds"},{"at":92.87,"dur":0.68,"text":"The catch?","who":"narrator","scene":"fovea"},{"at":93.97,"dur":3.31,"text":"Your sharpest vision only lives in one tiny spot.","who":"narrator","scene":"fovea"},{"at":97.54,"dur":1.82,"text":"Hold your thumb out at arm's length.","who":"narrator","scene":"fovea"},{"at":99.62,"dur":1.04,"text":"That tiny patch?","who":"narrator","scene":"fovea"},{"at":101.08,"dur":2.08,"text":"That's all your eyes see sharply at once.","who":"narrator","scene":"fovea"},{"at":103.42,"dur":1.09,"text":"So your eyes jump.","who":"narrator","scene":"fovea"},{"at":104.77,"dur":1.47,"text":"Three or four times a second.","who":"narrator","scene":"fovea"},{"at":106.5,"dur":0.97,"text":"Building the rest.","who":"narrator","scene":"fovea"},{"at":107.73,"dur":3.91,"text":"Except now, every jump brings in ten thousand times more detail.","who":"narrator","scene":"fovea"},{"at":111.9,"dur":0.95,"text":"And your brain...","who":"narrator","scene":"fovea"},{"at":113.4,"dur":1.23,"text":"has to sort all of it.","who":"narrator","scene":"fovea"},{"at":114.89,"dur":0.7,"text":"Headaches.","who":"narrator","scene":"fovea"},{"at":115.85,"dur":1.07,"text":"Every single day.","who":"narrator","scene":"fovea"},{"at":118.08,"dur":1.53,"text":"But where it gets really crazy...","who":"narrator","scene":"harbor"},{"at":120.16,"dur":0.81,"text":"is the video.","who":"narrator","scene":"harbor"},{"at":121.23,"dur":1.67,"text":"A tourist films you at the harbor.","who":"narrator","scene":"harbor"},{"at":123.16,"dur":2.83,"text":"You read a tiny warning sign on a ship far out at sea.","who":"narrator","scene":"harbor"},{"at":126.25,"dur":1.24,"text":"The clip goes everywhere.","who":"narrator","scene":"harbor"},{"at":128.65,"dur":1.41,"text":"By Friday, a message.","who":"narrator","scene":"message"},{"at":130.32,"dur":0.98,"text":"Mr. Black.","who":"narrator","scene":"message"},{"at":131.56,"dur":0.62,"text":"Polite.","who":"narrator","scene":"message"},{"at":132.44,"dur":0.55,"text":"Rich.","who":"narrator","scene":"message"},{"at":133.45,"dur":0.89,"text":"I have a job.","who":"black","scene":"message"},{"at":134.6,"dur":3.27,"text":"Sit in a café. Read a few phones. A few bank cards.","who":"black","scene":"message"},{"at":138.13,"dur":1.17,"text":"Nobody gets hurt.","who":"black","scene":"message"},{"at":139.56,"dur":1.23,"text":"Doesn't that sound easy?","who":"black","scene":"message"},{"at":142.11,"dur":1,"text":"And there's a cost.","who":"narrator","scene":"cost"},{"at":143.37,"dur":1.19,"text":"You can't switch it off.","who":"narrator","scene":"cost"},{"at":144.82,"dur":0.89,"text":"Peeling paint.","who":"narrator","scene":"cost"},{"at":145.97,"dur":1.2,"text":"Cracks in bridges.","who":"narrator","scene":"cost"},{"at":147.43,"dur":2.38,"text":"Mold in the bread before anyone else can see it.","who":"narrator","scene":"cost"},{"at":150.07,"dur":1.25,"text":"Your eyes never rest.","who":"narrator","scene":"cost"},{"at":151.58,"dur":1.81,"text":"And the world stops looking beautiful.","who":"narrator","scene":"cost"},{"at":153.65,"dur":0.95,"text":"It just looks...","who":"narrator","scene":"cost"},{"at":155.15,"dur":0.74,"text":"detailed.","who":"narrator","scene":"cost"},{"at":156.15,"dur":1.46,"text":"Sunsets turn into dust.","who":"narrator","scene":"cost"},{"at":157.87,"dur":1.42,"text":"Faces turn into maps.","who":"narrator","scene":"cost"},{"at":160.45,"dur":1.44,"text":"Then there's Grandpa Sam.","who":"narrator","scene":"grandpa"},{"at":162.15,"dur":1.97,"text":"He used to be a lifeguard on this beach.","who":"narrator","scene":"grandpa"},{"at":164.38,"dur":2.03,"text":"Now he has macular degeneration.","who":"narrator","scene":"grandpa"},{"at":166.67,"dur":1.22,"text":"It's a real disease.","who":"narrator","scene":"grandpa"},{"at":168.15,"dur":3.58,"text":"It slowly wipes out the center of your vision, while the edges stay.","who":"narrator","scene":"grandpa"},{"at":171.99,"dur":1.13,"text":"So you see the most.","who":"narrator","scene":"grandpa"},{"at":173.38,"dur":1.17,"text":"And he sees the least.","who":"narrator","scene":"grandpa"},{"at":175.71,"dur":2.28,"text":"Every Sunday, you climb the cliff together.","who":"narrator","scene":"cliff"},{"at":178.25,"dur":1.68,"text":"He flies his big red kite.","who":"narrator","scene":"cliff"},{"at":180.19,"dur":1.75,"text":"It's the one thing he still finds...","who":"narrator","scene":"cliff"},{"at":182.49,"dur":1.24,"text":"from the corner of his eye.","who":"narrator","scene":"cliff"},{"at":184.19,"dur":2.68,"text":"I can't see the gulls anymore, Theo.","who":"grandpa","scene":"cliff"},{"at":187.13,"dur":1.4,"text":"So you tell me.","who":"grandpa","scene":"cliff"},{"at":188.99,"dur":0.75,"text":"And you do.","who":"narrator","scene":"cliff"},{"at":190,"dur":0.74,"text":"Every wing.","who":"narrator","scene":"cliff"},{"at":191,"dur":0.82,"text":"Every wave.","who":"narrator","scene":"cliff"},{"at":192.08,"dur":1.19,"text":"You make a promise too.","who":"narrator","scene":"cliff"},{"at":193.73,"dur":0.96,"text":"If I can see it...","who":"theo","scene":"cliff"},{"at":195.24,"dur":1,"text":"it's mine to fix.","who":"theo","scene":"cliff"},{"at":197.4,"dur":0.93,"text":"Sunday comes.","who":"narrator","scene":"roof"},{"at":198.59,"dur":1.23,"text":"But you're not on the cliff.","who":"narrator","scene":"roof"},{"at":200.08,"dur":2.87,"text":"You're on a café roof, two kilometers down the coast.","who":"narrator","scene":"roof"},{"at":203.21,"dur":1.42,"text":"Mr. Black's job.","who":"narrator","scene":"roof"},{"at":204.89,"dur":2.19,"text":"Below you, a woman at a cash machine.","who":"narrator","scene":"roof"},{"at":207.34,"dur":0.68,"text":"Her card.","who":"narrator","scene":"roof"},{"at":208.28,"dur":0.7,"text":"Her keys.","who":"narrator","scene":"roof"},{"at":209.24,"dur":0.61,"text":"Her PIN.","who":"narrator","scene":"roof"},{"at":210.11,"dur":1.82,"text":"Mr. Black's voice in your ear.","who":"narrator","scene":"roof"},{"at":212.39,"dur":1,"text":"Four numbers, kid.","who":"black","scene":"roof"},{"at":213.65,"dur":0.84,"text":"Then you're done.","who":"black","scene":"roof"},{"at":215.65,"dur":0.56,"text":"Then...","who":"narrator","scene":"sea"},{"at":216.76,"dur":0.75,"text":"you see it.","who":"narrator","scene":"sea"},{"at":217.77,"dur":1.34,"text":"Far out past the beach.","who":"narrator","scene":"sea"},{"at":219.37,"dur":0.84,"text":"A small boy.","who":"narrator","scene":"sea"},{"at":220.47,"dur":1.2,"text":"On an orange board.","who":"narrator","scene":"sea"},{"at":221.93,"dur":0.72,"text":"Drifting...","who":"narrator","scene":"sea"},{"at":223.2,"dur":0.63,"text":"fast.","who":"narrator","scene":"sea"},{"at":224.09,"dur":1.75,"text":"The water around him is darker.","who":"narrator","scene":"sea"},{"at":226.1,"dur":0.6,"text":"Flatter.","who":"narrator","scene":"sea"},{"at":226.96,"dur":0.9,"text":"A rip current.","who":"narrator","scene":"sea"},{"at":228.12,"dur":2.37,"text":"Some rips move faster than an Olympic swimmer.","who":"narrator","scene":"sea"},{"at":230.75,"dur":1.78,"text":"Has anyone on the sand noticed?","who":"narrator","scene":"sea"},{"at":232.95,"dur":0.49,"text":"No.","who":"narrator","scene":"sea"},{"at":233.7,"dur":1.97,"text":"The lifeguard is looking the wrong way.","who":"narrator","scene":"sea"},{"at":235.93,"dur":0.98,"text":"Two kilometers.","who":"narrator","scene":"sea"},{"at":237.17,"dur":2.23,"text":"Even sprinting, you'd need six minutes.","who":"narrator","scene":"sea"},{"at":239.66,"dur":0.79,"text":"Maybe more.","who":"narrator","scene":"sea"},{"at":240.71,"dur":1.47,"text":"The board slips from his arms.","who":"narrator","scene":"sea"},{"at":243.34,"dur":0.54,"text":"Theo?","who":"black","scene":"choice"},{"at":244.3,"dur":1.01,"text":"The numbers. Now.","who":"black","scene":"choice"},{"at":245.77,"dur":1.35,"text":"You can see the PIN.","who":"narrator","scene":"choice"},{"at":247.38,"dur":1.14,"text":"You can see the boy.","who":"narrator","scene":"choice"},{"at":248.78,"dur":1.17,"text":"You can't have both.","who":"narrator","scene":"choice"},{"at":250.21,"dur":0.7,"text":"The money...","who":"narrator","scene":"choice"},{"at":251.46,"dur":0.75,"text":"or the boy.","who":"narrator","scene":"choice"},{"at":253.37,"dur":1.18,"text":"You drop the earpiece.","who":"narrator","scene":"call"},{"at":255.01,"dur":0.96,"text":"If I can see it...","who":"theo","scene":"call"},{"at":256.52,"dur":1,"text":"it's mine to fix.","who":"theo","scene":"call"},{"at":257.98,"dur":2.49,"text":"You call the one person on that beach you trust.","who":"narrator","scene":"call"},{"at":260.93,"dur":1.29,"text":"Grandpa. Kite. Up. Now.","who":"theo","scene":"call"},{"at":262.68,"dur":1.1,"text":"He doesn't ask why.","who":"narrator","scene":"call"},{"at":264.94,"dur":1.22,"text":"The red kite climbs.","who":"narrator","scene":"kite"},{"at":266.62,"dur":1.13,"text":"Left, Grandpa. More.","who":"theo","scene":"kite"},{"at":268.01,"dur":1.02,"text":"Stop. Hold it there.","who":"theo","scene":"kite"},{"at":269.49,"dur":1.47,"text":"Grandpa can't see the boy.","who":"narrator","scene":"kite"},{"at":271.22,"dur":1.28,"text":"But he can see his kite.","who":"narrator","scene":"kite"},{"at":272.76,"dur":2.49,"text":"And now it hangs right above that tiny head.","who":"narrator","scene":"kite"},{"at":276.41,"dur":1.6,"text":"You call the lifeguard station.","who":"narrator","scene":"nova"},{"at":278.27,"dur":1.16,"text":"Her name is Nova.","who":"narrator","scene":"nova"},{"at":279.89,"dur":1.06,"text":"Follow the red kite.","who":"theo","scene":"nova"},{"at":281.21,"dur":0.93,"text":"He's right under it.","who":"theo","scene":"nova"},{"at":282.6,"dur":1.64,"text":"Nova grabs the rescue board.","who":"narrator","scene":"nova"},{"at":284.5,"dur":1.36,"text":"She doesn't fight the current.","who":"narrator","scene":"nova"},{"at":286.12,"dur":1.04,"text":"She rides it out...","who":"narrator","scene":"nova"},{"at":287.71,"dur":1.17,"text":"then cuts sideways.","who":"narrator","scene":"nova"},{"at":289.14,"dur":1.32,"text":"And that's the real lesson.","who":"narrator","scene":"nova"},{"at":290.72,"dur":2.19,"text":"If a rip ever pulls you out, don't fight it.","who":"narrator","scene":"nova"},{"at":293.17,"dur":1.51,"text":"Swim parallel to the shore.","who":"narrator","scene":"nova"},{"at":294.94,"dur":1.1,"text":"Then come back in.","who":"narrator","scene":"nova"},{"at":297.2,"dur":2.79,"text":"Three minutes later, the boy is coughing on the sand.","who":"narrator","scene":"saved"},{"at":300.25,"dur":0.68,"text":"Alive...","who":"narrator","scene":"saved"},{"at":301.48,"dur":1.55,"text":"and furious about his board.","who":"narrator","scene":"saved"},{"at":303.29,"dur":2.71,"text":"The whole beach is cheering for an old man with a kite.","who":"narrator","scene":"saved"},{"at":307.16,"dur":1.13,"text":"And Mr. Black?","who":"narrator","scene":"police"},{"at":308.71,"dur":1.74,"text":"You never gave him a single number.","who":"narrator","scene":"police"},{"at":310.71,"dur":1.64,"text":"You gave the police something better.","who":"narrator","scene":"police"},{"at":312.61,"dur":0.69,"text":"His car.","who":"narrator","scene":"police"},{"at":313.56,"dur":0.73,"text":"His plate.","who":"narrator","scene":"police"},{"at":314.55,"dur":0.77,"text":"His face.","who":"narrator","scene":"police"},{"at":315.58,"dur":0.74,"text":"All read...","who":"narrator","scene":"police"},{"at":316.87,"dur":1.52,"text":"from two kilometers away.","who":"narrator","scene":"police"},{"at":318.65,"dur":1.69,"text":"Cover your PIN, by the way.","who":"narrator","scene":"police"},{"at":320.6,"dur":1.48,"text":"You never know who's watching.","who":"narrator","scene":"police"},{"at":323.24,"dur":1.83,"text":"That evening, you're back on the cliff.","who":"narrator","scene":"sunset"},{"at":325.33,"dur":1.46,"text":"Grandpa grips your shoulder.","who":"narrator","scene":"sunset"},{"at":327.25,"dur":1.52,"text":"Tell me what you see.","who":"grandpa","scene":"sunset"},{"at":329.23,"dur":3.13,"text":"For the first time in weeks, the world isn't just detail.","who":"narrator","scene":"sunset"},{"at":332.62,"dur":1.03,"text":"It's gold water.","who":"narrator","scene":"sunset"},{"at":333.91,"dur":0.87,"text":"A red kite.","who":"narrator","scene":"sunset"},{"at":335.04,"dur":1.73,"text":"And a family hugging a little boy.","who":"narrator","scene":"sunset"},{"at":337.03,"dur":0.73,"text":"Beautiful.","who":"narrator","scene":"sunset"},{"at":338.92,"dur":1.14,"text":"Is any of this real?","who":"narrator","scene":"real"},{"at":340.48,"dur":0.61,"text":"Partly.","who":"narrator","scene":"real"},{"at":341.35,"dur":4.18,"text":"Macular degeneration is real, and it steals central vision first.","who":"narrator","scene":"real"},{"at":345.79,"dur":1.5,"text":"Rip currents are real too.","who":"narrator","scene":"real"},{"at":347.55,"dur":1.65,"text":"But eyes a hundred times sharper?","who":"narrator","scene":"real"},{"at":349.62,"dur":0.99,"text":"Physics says no.","who":"narrator","scene":"real"},{"at":350.87,"dur":2.48,"text":"Light spreads out as it passes through your pupil.","who":"narrator","scene":"real"},{"at":353.61,"dur":2.53,"text":"A normal pupil is a few millimeters wide.","who":"narrator","scene":"real"},{"at":356.4,"dur":1.41,"text":"That's already near the limit.","who":"narrator","scene":"real"},{"at":358.07,"dur":1.38,"text":"A hundred times sharper?","who":"narrator","scene":"real"},{"at":359.87,"dur":2.11,"text":"You'd need pupils a hundred times wider.","who":"narrator","scene":"real"},{"at":362.24,"dur":1.58,"text":"Roughly thirty centimeters.","who":"narrator","scene":"real"},{"at":364.08,"dur":0.63,"text":"Eyes...","who":"narrator","scene":"real"},{"at":365.26,"dur":1.24,"text":"the size of pizzas.","who":"narrator","scene":"real"},{"at":366.76,"dur":2.74,"text":"Which, to be fair, would make birdwatching awkward.","who":"narrator","scene":"real"},{"at":370.66,"dur":1.64,"text":"That night, you look up at the Moon.","who":"narrator","scene":"sting"},{"at":372.56,"dur":1.5,"text":"And something on its surface...","who":"narrator","scene":"sting"},{"at":374.61,"dur":0.65,"text":"moves.","who":"narrator","scene":"sting"},{"at":376.42,"dur":2.86,"text":"So would you trade normal eyes for pizza-sized ones?","who":"narrator","scene":"cta"},{"at":379.7,"dur":0.88,"text":"What do you think?","who":"narrator","scene":"cta"},{"at":381,"dur":3.85,"text":"Tell us in the comments, and tell us which superpower we should do next.","who":"narrator","scene":"cta"},{"at":385.11,"dur":2.18,"text":"Hit like, and subscribe for Part Two.","who":"narrator","scene":"cta"}],"scenes":[{"id":"beach","t0":0,"t1":9.42},{"id":"moon","t0":9.42,"t1":15.27},{"id":"hill","t0":15.27,"t1":26.42},{"id":"plate","t0":26.42,"t1":35.71},{"id":"acuity","t0":35.71,"t1":43.57},{"id":"rule","t0":43.57,"t1":55.12},{"id":"title","t0":55.12,"t1":59.07},{"id":"class","t0":59.07,"t1":78.56},{"id":"stadium","t0":78.56,"t1":85.39},{"id":"birds","t0":85.39,"t1":92.42},{"id":"fovea","t0":92.42,"t1":117.63},{"id":"harbor","t0":117.63,"t1":128.2},{"id":"message","t0":128.2,"t1":141.66},{"id":"cost","t0":141.66,"t1":160},{"id":"grandpa","t0":160,"t1":175.26},{"id":"cliff","t0":175.26,"t1":196.95},{"id":"roof","t0":196.95,"t1":215.2},{"id":"sea","t0":215.2,"t1":242.89},{"id":"choice","t0":242.89,"t1":252.92},{"id":"call","t0":252.92,"t1":264.49},{"id":"kite","t0":264.49,"t1":275.96},{"id":"nova","t0":275.96,"t1":296.75},{"id":"saved","t0":296.75,"t1":306.71},{"id":"police","t0":306.71,"t1":322.79},{"id":"sunset","t0":322.79,"t1":338.47},{"id":"real","t0":338.47,"t1":370.21},{"id":"sting","t0":370.21,"t1":375.97},{"id":"cta","t0":375.97,"t1":392.05}]};
if (typeof module !== 'undefined') module.exports = TL; else globalThis.TIMELINE = TL; })();
